css:
/* Nature / Sustainability theme — Costaria climate-policy lab */
.costaria-sim-container {
    padding: 24px;
    background: linear-gradient(180deg, #d8f3dc 0%, #b7e4c7 60%, #95d5b2 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    color: #1b4332;
}

.costaria-sim-container h1,
.costaria-sim-container h3 {
    margin: 0;
    color: inherit;
    font-weight: 700;
}

/* HEADER */
.costaria-sim-header {
    margin-bottom: 24px;
}
.costaria-sim-header-band {
    background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 60%, #40916c 100%);
    border-radius: 24px;
    padding: 28px 32px;
    color: #d8f3dc;
    box-shadow: 0 14px 36px rgba(27, 67, 50, 0.28);
    display: flex;
    align-items: center;
    gap: 20px;
}
.costaria-sim-flag {
    font-size: 3rem;
    flex-shrink: 0;
}
.costaria-sim-header-text h1 {
    font-size: 1.7rem;
    color: #d8f3dc;
    letter-spacing: 0.01em;
}
.costaria-sim-subtitle {
    color: #b7e4c7;
    font-size: 0.95rem;
    margin-top: 6px;
    font-style: italic;
}

/* PERIOD BAR */
.costaria-sim-period-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 20px;
    align-items: center;
}
.costaria-sim-period-pill {
    background: #1b4332;
    color: #d8f3dc;
    padding: 8px 18px;
    border-radius: 999px;
    font-size: 0.95rem;
    display: inline-flex;
    align-items: baseline;
    gap: 6px;
}
.costaria-sim-period-pill strong {
    color: #ffffff;
    font-size: 1.05rem;
}
.costaria-sim-period-pill-light {
    background: #52b788;
    color: #194030;
}
.costaria-sim-period-pill-light strong {
    color: #1b4332;
}
.costaria-sim-target-pill {
    margin-left: auto;
    background: #ffffff;
    border: 2px solid #2d6a4f;
    color: #1b4332;
    padding: 6px 18px;
    border-radius: 999px;
    font-size: 0.9rem;
    display: inline-flex;
    align-items: baseline;
    gap: 8px;
}
.costaria-sim-target-pill strong {
    color: #2d6a4f;
}

/* BRIEFING */
.costaria-sim-briefing {
    background: #ffffff;
    border-left: 6px solid #d62828;
    border-radius: 12px;
    padding: 18px 22px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06);
    line-height: 1.55;
}
.costaria-sim-briefing-title {
    text-transform: uppercase;
    letter-spacing: 0.16em;
    font-size: 0.78rem;
    color: #d62828;
    font-weight: 700;
    margin-bottom: 6px;
}
#briefingText {
    color: #1b4332;
    font-size: 1rem;
}

/* STATUS CARDS */
.costaria-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}
.costaria-sim-status-card {
    background: #ffffff;
    border-radius: 18px;
    padding: 22px 20px;
    box-shadow: 0 6px 20px rgba(27, 67, 50, 0.08);
    border-top: 5px solid #52b788;
    position: relative;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.costaria-sim-status-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 26px rgba(27, 67, 50, 0.14);
}
.costaria-sim-card-emissions   { border-top-color: #d62828; }
.costaria-sim-card-reduction   { border-top-color: #2d6a4f; }
.costaria-sim-card-revenue     { border-top-color: #f4a261; }
.costaria-sim-card-political   { border-top-color: #4361ee; }
.costaria-sim-card-distrib     { border-top-color: #9d4edd; }
.costaria-sim-card-rnd         { border-top-color: #06a77d; }

.costaria-sim-label {
    color: #6c757d;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.10em;
    margin-bottom: 8px;
    font-weight: 600;
}
.costaria-sim-value {
    font-size: 2rem;
    font-weight: 700;
    color: #1b4332;
    line-height: 1.1;
}
.costaria-sim-sub {
    color: #52796f;
    font-size: 0.78rem;
    margin-top: 6px;
}

/* CONTROLS */
.costaria-sim-controls {
    background: #ffffff;
    border-radius: 20px;
    padding: 26px 28px;
    margin-bottom: 26px;
    box-shadow: 0 6px 20px rgba(27, 67, 50, 0.08);
    border: 1px solid #b7e4c7;
}
.costaria-sim-controls h3 {
    color: #1b4332;
    font-size: 1.15rem;
    margin-bottom: 18px;
    border-bottom: 2px solid #d8f3dc;
    padding-bottom: 8px;
}
.costaria-sim-controls-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 20px;
}
.costaria-sim-control {
    display: flex;
    flex-direction: column;
}
.costaria-sim-control label {
    font-size: 0.85rem;
    font-weight: 600;
    color: #2d6a4f;
    margin-bottom: 6px;
}
.costaria-sim-controls input[type="number"],
.costaria-sim-controls input[type="text"],
.costaria-sim-controls select {
    background: #ffffff;
    border: 1.5px solid #95d5b2;
    color: #1b4332;
    border-radius: 10px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.95rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.costaria-sim-controls input[type="number"]:focus,
.costaria-sim-controls select:focus {
    outline: none;
    border-color: #2d6a4f;
    box-shadow: 0 0 0 3px rgba(45, 106, 79, 0.18);
}
.costaria-sim-controls select option {
    background: #ffffff;
    color: #1b4332;
}
.costaria-sim-actions {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    align-items: center;
}
.costaria-sim-controls .btn-primary {
    background: linear-gradient(135deg, #2d6a4f, #40916c);
    border: none;
    border-radius: 10px;
    padding: 10px 26px;
    color: #d8f3dc;
    font-weight: 600;
    letter-spacing: 0.02em;
    box-shadow: 0 6px 16px rgba(27, 67, 50, 0.18);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.costaria-sim-controls .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 10px 22px rgba(27, 67, 50, 0.24);
}
.costaria-sim-controls .btn-outline-secondary {
    background: transparent;
    color: #2d6a4f;
    border: 1.5px solid #95d5b2;
    border-radius: 10px;
    padding: 8px 18px;
}
.costaria-sim-controls .btn-outline-secondary:hover {
    background: #d8f3dc;
    color: #1b4332;
}

/* CHARTS */
.costaria-sim-charts-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 18px;
    margin-bottom: 26px;
}
.costaria-sim-chart-panel {
    background: #ffffff;
    border-radius: 18px;
    padding: 18px 20px;
    height: 320px;
    box-shadow: 0 6px 20px rgba(27, 67, 50, 0.08);
    border: 1px solid #b7e4c7;
}

/* HISTORY TABLE */
.costaria-sim-history-panel {
    background: #ffffff;
    border-radius: 18px;
    padding: 22px 24px;
    box-shadow: 0 6px 20px rgba(27, 67, 50, 0.08);
    border: 1px solid #b7e4c7;
    overflow-x: auto;
}
.costaria-sim-history-panel h3 {
    color: #1b4332;
    font-size: 1.05rem;
    margin-bottom: 14px;
    border-bottom: 2px solid #d8f3dc;
    padding-bottom: 6px;
}
.costaria-sim-history-panel table {
    width: 100%;
    color: #1b4332;
    font-size: 0.92rem;
}
.costaria-sim-history-panel thead th {
    background: #2d6a4f;
    color: #d8f3dc;
    font-weight: 600;
    border: none;
    padding: 10px 12px;
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
.costaria-sim-history-panel tbody td {
    padding: 8px 12px;
    border-bottom: 1px solid #d8f3dc;
}
.costaria-sim-history-panel tbody tr:nth-child(even) {
    background: #f1faf3;
}

/* RESPONSIVE */
@media (max-width: 768px) {
    .costaria-sim-container { padding: 14px; }
    .costaria-sim-header-band { padding: 20px; flex-direction: column; align-items: flex-start; }
    .costaria-sim-header-text h1 { font-size: 1.3rem; }
    .costaria-sim-flag { font-size: 2.2rem; }
    .costaria-sim-target-pill { margin-left: 0; }
    .costaria-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .costaria-sim-value { font-size: 1.4rem; }
    .costaria-sim-controls-grid { grid-template-columns: 1fr; }
    .costaria-sim-chart-panel { height: 260px; }
}


/* --- EQIL a11y additions (2026-08-08) --- */
.costaria-sim-container :focus-visible {
    outline: 3px solid #1b4332;
    outline-offset: 2px;
}
.costaria-sim-debrief {
    margin-top: 20px;
    padding: 20px 24px;
    background: #ffffff;
    border: 1px solid #d5e2d9;
    border-radius: 10px;
    color: #1b4332;
}
.costaria-sim-debrief h3 { margin: 0 0 8px; font-size: 1.05rem; }
.costaria-sim-debrief-score { font-size: 1.1rem; margin: 0 0 12px; }
.costaria-sim-debrief-kpis, .costaria-sim-debrief-insights { margin: 0 0 12px; padding-left: 20px; }
.costaria-sim-debrief-lead { font-weight: 600; margin: 0 0 6px; }
@media (prefers-reduced-motion: reduce) {
    .costaria-sim-container *, .costaria-sim-container *::before, .costaria-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

