            if (pc) { pc.setAttribute('role', 'img'); pc.setAttribute('aria-label', t('chart_alt_political')); }
            if (idx >= this.ROUNDS.length) {
                if (briefEl) briefEl.innerHTML = t(`briefing_done_text`);
                if (yearEl) yearEl.textContent = t(`year_done`);
                var dp = document.getElementById(`decisionsPanel`);
                if (dp) dp.style.display = `none`;
                var ar = document.getElementById(`actionRow`);
                if (ar) ar.style.display = `none`;
                return;
            }
            var round = this.ROUNDS[idx];
            if (briefEl) briefEl.innerHTML = t(round.key);
            if (yearEl) yearEl.textContent = round.year;
        }

        _syncControlsFromDecisions(decisions) {
            if (!decisions) return;
            var map = {
                instrumentSelect: decisions.instrument,
                priceInput: decisions.carbonPrice,
                coverageInput: decisions.coverage,
                revenueSelect: decisions.revenueUse,
                cbamSelect: decisions.borderAdjustment,
                allocationSelect: decisions.allocation,
                rndInput: decisions.rndSubsidyB
            };
            for (var id in map) {
                if (!Object.prototype.hasOwnProperty.call(map, id)) continue;
                var el = document.getElementById(id);
                if (el && map[id] !== undefined && map[id] !== null) el.value = String(map[id]);
            }
        }

        _composite(finalReduction, finalPolitical, avgNetBenefit, rndStock) {
            var clamp = function(v) { return Math.max(0, Math.min(1, v)); };
            // full marks at the committed 115 Mt, the figure in the case and in the header
            var ndc = clamp(finalReduction / this._ndcReductionPct());
            var pol = clamp((finalPolitical - 20) / 45);
            var fair = clamp((avgNetBenefit + 1.5) / 2.5);
            var rnd = clamp(rndStock / 6);
            return Math.round(100 * (0.40 * ndc + 0.25 * pol + 0.20 * fair + 0.15 * rnd));
        }

        _ndcReductionPct() {
            return 100 * (this.BASELINE_EMISSIONS - this.NDC_TARGET) / this.BASELINE_EMISSIONS;
        }

        _band(composite) {
            if (composite >= 85) return `excellent`;
            if (composite >= 70) return `good`;
            if (composite >= 50) return `developing`;
            return `beginner`;
        }

        validateDecisions(decisions) {
            var instrumentEl = document.getElementById(`instrumentSelect`);
            if (instrumentEl) decisions.instrument = instrumentEl.value;

            var priceEl = document.getElementById(`priceInput`);
            if (priceEl) decisions.carbonPrice = parseFloat(priceEl.value);

            var coverageEl = document.getElementById(`coverageInput`);
            if (coverageEl) decisions.coverage = parseFloat(coverageEl.value);

            var revenueEl = document.getElementById(`revenueSelect`);
            if (revenueEl) decisions.revenueUse = revenueEl.value;

            var cbamEl = document.getElementById(`cbamSelect`);
            if (cbamEl) decisions.borderAdjustment = cbamEl.value;

            var allocEl = document.getElementById(`allocationSelect`);
            if (allocEl) decisions.allocation = allocEl.value;

            var rndEl = document.getElementById(`rndInput`);
            if (rndEl) decisions.rndSubsidyB = parseFloat(rndEl.value);

            if (isNaN(decisions.carbonPrice) || decisions.carbonPrice < 0 || decisions.carbonPrice > 200) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t(`price_warning`), `warning`
                );
                return false;
            }
            if (isNaN(decisions.coverage) || decisions.coverage < 20 || decisions.coverage > 95) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t(`coverage_warning`), `warning`
                );
                return false;
            }
            if (isNaN(decisions.rndSubsidyB) || decisions.rndSubsidyB < 0 || decisions.rndSubsidyB > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t(`rnd_warning`), `warning`
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;

            var price = parseFloat(d.carbonPrice) || 0;
            var coverage = parseFloat(d.coverage) || 0;
            var rnd = parseFloat(d.rndSubsidyB) || 0;

            ds.rndStockClean += rnd;
            var rndBoost = 1 + Math.min(ds.rndStockClean / 18, 0.35);

            var covFactor = Math.max(0.05, Math.min(coverage / 100, 0.95));
            var sensitivity = 0.70 * rndBoost;

            var equilibrium = this.BASELINE_EMISSIONS * Math.exp(-price * covFactor * sensitivity / 100);
            var adjSpeed = 0.30;
            var gap = ds.emissions - equilibrium;
            if (gap < 0) gap = 0;
            var rawAbatement = gap * adjSpeed;

            var leakageRate = 0;
            if (d.borderAdjustment === `none`) leakageRate = 0.30;
            else if (d.borderAdjustment === `partial`) leakageRate = 0.12;
            else leakageRate = 0;

            var instrumentBoost = 1.0;
            if (d.instrument === `hybrid`) instrumentBoost = 1.08;
            else if (d.instrument === `ets`) instrumentBoost = 1.02;

            var actualAbatement = rawAbatement * (1 - leakageRate) * instrumentBoost;
            var newEmissions = ds.emissions - actualAbatement;
            if (newEmissions < 80) newEmissions = 80;
            actualAbatement = ds.emissions - newEmissions;
            ds.emissions = newEmissions;
            ds.cumulativeAbatement += actualAbatement;

            var revShare = 1.0;
            if (d.instrument === `ets` && d.allocation === `grandfather`) revShare = 0;
            var yearRevenueUSD = price * covFactor * ds.emissions / 1000 * revShare;
            var yearRevenueCOP = yearRevenueUSD * 11;
            ds.totalRevenue += yearRevenueCOP;

            var grossBurden = price * covFactor * 0.05;
            // Recycling can only return money that was raised. recycledShare is the revenue left
            // after the clean R and D subsidy is paid out of it, as a share of what this price and
            // coverage would raise on baseline emissions. It is 1 at the start and falls as the
            // tax base shrinks; it is 0 when permits are given away (TN 5.3, 5.4 and 13).
            var baseRevenueCOP = price * covFactor * this.BASELINE_EMISSIONS / 1000 * 11;
            var recyclable = Math.max(0, yearRevenueCOP - rnd);
            var recycledShare = baseRevenueCOP > 0 ? Math.min(1, recyclable / baseRevenueCOP) : 0;
            var returnFactor = 0.5;
            if (d.revenueUse === 'dividend') returnFactor = 2.4;
            else if (d.revenueUse === 'mixed') returnFactor = 1.4;
            else if (d.revenueUse === 'rnd') returnFactor = 0.3;
            var netBurden = grossBurden - grossBurden * returnFactor * recycledShare;

            ds.distributionalNetBenefit = parseFloat((-netBurden).toFixed(2));

            var politicalChange = 0;
            // with no revenue raised there is nothing to recycle, whatever the revenue use says
            if (!(yearRevenueCOP > 0)) politicalChange -= 2;
            else if (d.revenueUse === 'dividend') politicalChange += 4;
            else if (d.revenueUse === `mixed`) politicalChange += 2;
            else if (d.revenueUse === `rnd`) politicalChange -= 1;
            else politicalChange -= 2;
            if (d.borderAdjustment === `full`) politicalChange += 2;
            else if (d.borderAdjustment === `partial`) politicalChange += 1;
            if (price > 80) politicalChange -= 2;
            if (price > 120) politicalChange -= 4;
            if (price < 15) politicalChange -= 1;
            if (rnd > 0.5) politicalChange += 1;
            if (netBurden > 1.5) politicalChange -= 4;
            if (d.instrument === `ets` && d.allocation === `grandfather`) politicalChange -= 2;

            ds.politicalSupport = Math.max(0, Math.min(100, ds.politicalSupport + politicalChange));

            var reductionPct = ((this.BASELINE_EMISSIONS - ds.emissions) / this.BASELINE_EMISSIONS) * 100;

            ds.emissionsHistory.push(parseFloat(ds.emissions.toFixed(2)));
            ds.priceHistory.push(price);
            ds.politicalHistory.push(ds.politicalSupport);
            ds.reductionPctHistory.push(parseFloat(reductionPct.toFixed(2)));
            ds.revenueHistory.push(parseFloat(yearRevenueCOP.toFixed(2)));
            var trajectoryEmissions = this.BASELINE_EMISSIONS - state.currentPeriod *
                ((this.BASELINE_EMISSIONS - this.NDC_TARGET) / this.ROUNDS.length);
            ds.targetTrajectory.push(parseFloat(trajectoryEmissions.toFixed(2)));

            // USF contract C1: the running grade, from the same composite the debrief uses
            ds.netBenefitSum = (ds.netBenefitSum || 0) + ds.distributionalNetBenefit;
            ds.netBenefitYears = (ds.netBenefitYears || 0) + 1;
            var runningScore = this._composite(reductionPct, ds.politicalSupport,
                ds.netBenefitSum / ds.netBenefitYears, ds.rndStockClean);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: runningScore });

            var self = this;
            var nextPeriod = state.currentPeriod + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 400);

            return {
                period: state.currentPeriod,
                year: 2026 + state.currentPeriod,
                instrument: d.instrument,
                price: price,
                coverage: coverage,
                revenueUse: d.revenueUse,
                borderAdjustment: d.borderAdjustment,
                allocation: d.allocation,
                rndSubsidy: rnd,
                emissions: parseFloat(ds.emissions.toFixed(2)),
                abatement: parseFloat(actualAbatement.toFixed(2)),
                revenue: parseFloat(yearRevenueCOP.toFixed(2)),
                cumulativeRevenue: parseFloat(ds.totalRevenue.toFixed(2)),
                reductionPct: parseFloat(reductionPct.toFixed(2)),
                netBenefitBottom60: parseFloat((-netBurden).toFixed(2)),
                politicalSupport: ds.politicalSupport,
                leakage: parseFloat((leakageRate * 100).toFixed(0)),
                overallScore: runningScore,
                score: runningScore
            };
        }

