        getHint(state, results) {
            if (!results) return null;
            if (results.reductionPct < 5 && state.currentPeriod >= 3) {
                return window.mySimulation.t(`hint_low_progress`);
            }
            if (results.netBenefitBottom60 < -1.0) {
                return window.mySimulation.t(`hint_regressive`);
            }
            if (results.politicalSupport < 30) {
                return window.mySimulation.t(`hint_political_risk`);
            }
            if (results.leakage >= 25 && results.coverage > 50) {
                return window.mySimulation.t(`hint_leakage`);
            }
            if (state.currentPeriod >= 4 && state.domainState.rndStockClean < 1) {
                return window.mySimulation.t(`hint_no_rnd`);
            }
            if (results.instrument === `ets` && results.allocation === `grandfather`) {
                return window.mySimulation.t(`hint_grandfather`);
            }
            if (results.price > 130) {
                return window.mySimulation.t(`hint_high_price`);
            }
            return null;
        }

        _optLabel(v) {
