        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1];
            var ds = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.domainState : null;
            var finalEmissions = ds ? ds.emissions : (last.results ? last.results.emissions : 165);
            var finalReduction = ((165 - finalEmissions) / 165) * 100;
            var finalPolitical = ds ? ds.politicalSupport : (last.results ? last.results.politicalSupport : 50);
            var totalRevenue = ds ? ds.totalRevenue : 0;
            var rndStock = ds ? ds.rndStockClean : 0;
            var avgNetBenefit = 0;
            if (history.length) {
                var sum = 0; var n = 0;
                history.forEach(h => {
                    if (h.results && typeof h.results.netBenefitBottom60 === `number`) {
                        sum += h.results.netBenefitBottom60; n++;
                    }
                });
                if (n) avgNetBenefit = sum / n;
            }

            var performance = `Beginner`;
            // each verdict is read at the point where its score component reaches full marks
            var ndcMet = finalReduction >= this._ndcReductionPct() - 1e-9;
            var politicallyDurable = finalPolitical >= 65;
            var distributionallyFair = avgNetBenefit >= 1.0;
            var hasRnd = rndStock >= 6;

            var passes = 0;
            if (ndcMet) passes++;
            if (politicallyDurable) passes++;
            if (distributionallyFair) passes++;
            if (hasRnd) passes++;
            var composite = this._composite(finalReduction, finalPolitical, avgNetBenefit, rndStock);
            performance = this._band(composite);

            var insights = [];
            if (ndcMet) insights.push(window.mySimulation.t(`insight_ndc_met`));
            else insights.push(window.mySimulation.t(`insight_ndc_missed`));
            if (politicallyDurable) insights.push(window.mySimulation.t(`insight_politically_durable`));
            else insights.push(window.mySimulation.t(`insight_political_risk`));
            if (distributionallyFair) insights.push(window.mySimulation.t(`insight_distrib_fair`));
            else if (avgNetBenefit >= 0) insights.push(window.mySimulation.t('insight_distrib_thin'));
            else insights.push(window.mySimulation.t(`insight_distrib_unfair`));
            if (hasRnd) insights.push(window.mySimulation.t(`insight_aabh_yes`));
            else insights.push(window.mySimulation.t(`insight_aabh_no`));

            // the plays this run actually made, read from its own history (TN 13 and Q2 to Q5)
            var made = this._mistakesMade(history);
            var mistakeLines = made.map(function(k) { return window.mySimulation.t('mistake_' + k); });
            var turning = this._turningPoint(history);

            var t = function(k) {
                return (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(k) : k;
            };
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                criteriaPassed: passes,
                rounds: history.length,
                performanceKey: performance,
                performanceLabel: t(`perf_` + performance),
                ndcMet: ndcMet,
                finalReduction: parseFloat(finalReduction.toFixed(2)),
                finalEmissions: parseFloat(finalEmissions.toFixed(2)),
                finalPoliticalSupport: Math.round(finalPolitical),
                cumulativeRevenue: parseFloat(totalRevenue.toFixed(2)),
                cleanRndStock: parseFloat(rndStock.toFixed(2)),
                avgNetBenefitBottom60: parseFloat(avgNetBenefit.toFixed(2)),
                performance: performance,
                insights: insights,
                mistakes: made,
                mistakeLines: mistakeLines,
                turningPoint: turning
            };
        }

        _mistakesMade(history) {
            var rows = (history || []).map(function(h) { return h.decisions || {}; });
            var num = function(v) { var x = parseFloat(v); return isFinite(x) ? x : 0; };
            var out = [];
            if (rows.some(function(d) { return num(d.carbonPrice) > 120 && d.revenueUse === 'general'; })) out.push('textbook');
            if (rows.length && num(rows[0].carbonPrice) > 80) out.push('jump');
            if (rows.some(function(d) { return d.revenueUse === 'rnd'; })) out.push('rndfund');
            var subsidy = rows.reduce(function(a, d) { return a + num(d.rndSubsidyB); }, 0);
            if (rows.length >= 4 && subsidy === 0) out.push('pricealone');
            if (rows.some(function(d) { return d.instrument === 'ets' && d.allocation === 'grandfather'; })) out.push('freepermits');
            return out;
        }

        _turningPoint(history) {
            var h = history || [];
            var target = this.NDC_TARGET;
            for (var i = 0; i < h.length; i++) {
                var r = h[i].results || {};
                if (typeof r.emissions === 'number' && r.emissions <= target) {
                    return { kind: 'crossed', year: r.year || (2027 + i) };
                }
            }
            var worst = null; var prev = 50;
            for (var j = 0; j < h.length; j++) {
                var rr = h[j].results || {};
                if (typeof rr.politicalSupport !== 'number') continue;
                var drop = prev - rr.politicalSupport;
                if (drop > 0 && (!worst || drop > worst.drop)) worst = { kind: 'support', year: rr.year || (2027 + j), drop: drop };
                prev = rr.politicalSupport;
            }
            return worst || { kind: 'none', year: null };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var t = function(k) {
                return (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(k) : k;
            };
            var n = function(v, dp, fb) {
                return (typeof v === `number` && isFinite(v)) ? v.toFixed(dp) : fb;
            };
            var items = (s.insights || []).map(function(x) { return `<li>` + x + `</li>`; }).join(``);
            var tp = s.turningPoint || { kind: 'none' };
            var tpText = t('tp_' + tp.kind).split('{year}').join(String(tp.year || '')).split('{drop}').join(String(tp.drop || 0));
            var mistakeItems = (s.mistakeLines || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var mistakeBlock = mistakeItems
                ? '<p class="costaria-sim-debrief-lead">' + t('debrief_mistakes') + '</p><ul class="costaria-sim-debrief-insights">' + mistakeItems + '</ul>'
                : '';
            return `` +
                `<div class="costaria-sim-debrief">` +
                `<h3>` + t(`debrief_title`) + `</h3>` +
                `<p class="costaria-sim-debrief-score"><strong>` +
                    (typeof s.overallScore === `number` ? s.overallScore : 0) + ` / 100</strong> — ` +
                    (s.performanceLabel || t(`perf_beginner`)) + `</p>` +
                `<ul class="costaria-sim-debrief-kpis">` +
                `<li>` + t(`debrief_reduction`) + `: <strong>` + n(s.finalReduction, 1, `0.0`) + `%</strong> (` +
                    t(s.ndcMet ? `debrief_ndc_met` : `debrief_ndc_missed`) + `)</li>` +
                `<li>` + t(`debrief_political`) + `: <strong>` + n(s.finalPoliticalSupport, 0, `0`) + `/100</strong></li>` +
                `<li>` + t(`debrief_distrib`) + `: <strong>` + n(s.avgNetBenefitBottom60, 2, `0.00`) + `</strong></li>` +
                `<li>` + t(`debrief_rnd`) + `: <strong>` + n(s.cleanRndStock, 2, `0.00`) + `</strong></li>` +
                `<li>` + t(`debrief_revenue`) + `: <strong>` + n(s.cumulativeRevenue, 2, `0.00`) + `</strong></li>` +
